"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[6655],{5984(e){e.exports=JSON.parse('{"tag":{"label":"Principle of Optimality","permalink":"/concepts/tags/principle-of-optimality","allTagsPath":"/concepts/tags","count":1,"items":[{"id":"algorithm-design-paradigms/dynamic-programming","title":"Dynamic Programming","description":"Divide and conquer breaks a problem into subproblems and combines their solutions. It works beautifully when the subproblems are independent. But we saw in the divide and conquer chapter that the naive recursive Fibonacci solves the same subproblems again and again, and becomes exponential. Dynamic programming keeps the idea of solving a problem through its subproblems, but solves each subproblem only once, storing its solution in a table for later use.","permalink":"/concepts/algorithm-design-paradigms/dynamic-programming"}],"unlisted":false}}')}}]);